/// <summary>
/// MarkupCode.modified extension
/// </summary>
public void modified()
{
    FormDataObject formDataObject = any2Object(this) as FormDataObject;
    FormDataSource formDataSource = formDataObject.datasource();

    next modified();

    // Update rebate controls enabled/mandatory from MarkupCode.modified method
    METMarkupAutoSetupHelper markupAutoSetupHelper = METMarkupAutoSetupHelper::newFromFormRun(formDataSource.formRun());
    markupAutoSetupHelper.updateRebateControlsEnabled(formDataSource);

}
